#include <WiFi.h>
#include <WebServer.h>

const char* ssid = "ArduSim_Network";
const char* password = "Ardusim@123";

WebServer server(80);

const int ledPin = 16;      // GPIO 16 assigned to LED
const int freq = 5000;      // 5 kHz PWM frequency
const int resolution = 8;   // 8-bit resolution (0-255)

const char htmlPage[] = R"rawliteral(
<!DOCTYPE html>
<html>
<head>
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>ESP32 LED Dimmer</title>
  <style>
    body { font-family: Arial; text-align: center; margin-top: 50px; background: #f4f4f4; }
    h1 { color: #333; }
    .slider { width: 80%; max-width: 400px; height: 25px; }
    p { font-size: 1.2rem; }
  </style>
</head>
<body>
  <h1>ESP32 LED Brightness Control</h1>
  <p>Brightness: <span id="valBox">0</span></p>
  <p><input type="range" min="0" max="255" value="0" class="slider" id="pwmSlider" oninput="updateSlider(this.value)"></p>

  <script>
    function updateSlider(val) {
      document.getElementById('valBox').innerHTML = val;
      fetch('/slider?value=' + val).catch(err => console.error(err));
    }
  </script>
</body>
</html>
)rawliteral";

void handleRoot() {
  server.send(200, "text/html", htmlPage);
}

void handleSlider() {
  if (server.hasArg("value")) {
    int sliderValue = server.arg("value").toInt();
    ledcWrite(ledPin, sliderValue); // Updates the PWM duty cycle
  }
  server.send(200, "text/plain", "OK");
}

void setup() {
  Serial.begin(115200);

  // Configure LED PWM for v3.x API
  ledcAttach(ledPin, freq, resolution);
  ledcWrite(ledPin, 0);

  WiFi.begin(ssid, password);
  while (WiFi.status() != WL_CONNECTED) {
    delay(500);
    Serial.print(".");
  }

  Serial.println("\nWiFi connected. IP address: ");
  Serial.println(WiFi.localIP());

  server.on("/", handleRoot);
  server.on("/slider", handleSlider);
  server.begin();
}

void loop() {
  server.handleClient();
}
